function exportAudit464(){const payload={schema:'gray-audit/1',app_version:fileVersion464,date:new Date().toISOString(),cal:state.cal,markReviews:state.reviewMarks,imageReviews:state.imageReviews,evidence:state.evidence};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download='gray464_audyt_lokalny.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),2500)}
async function importAudit464(file){if(!file)return;try{
 if(file.size>2_000_000)throw Error('Plik audytu jest za duży (limit 2 MB).');const d=JSON.parse(await file.text());if(d.schema!=='gray-audit/1')throw Error('Nieobsługiwany schemat audytu.');
 const object=x=>x&&typeof x==='object'&&!Array.isArray(x);if(!object(d.cal)||!object(d.markReviews)||!object(d.imageReviews)||!object(d.evidence))throw Error('Niepoprawny format danych.');
 const allowedImages=new Set(Object.keys(DATA.assets));const allowedStructs=new Set([...DATA.atlas,...DATA.extra].flatMap(r=>(r.structures||r.layers?.flatMap(l=>l.structures||[])||[]).map(s=>s.id)));
 const validateKey=k=>{const parts=k.split('|');return parts.length===2&&allowedImages.has(parts[0])&&allowedStructs.has(parts[1])};
 const cal={};for(const [k,p] of Object.entries(d.cal)){if(validateKey(k)&&Array.isArray(p)&&p.length===4&&p.every(x=>Number.isFinite(x)&&x>=0&&x<=1))cal[k]=p;else throw Error('Błędny punkt lub nieznana struktura: '+k.slice(0,70));}
 const rev={};for(const [k,v] of Object.entries(d.markReviews)){if(validateKey(k)&&['nieoceniony','przejrzano-lokalnie','wymaga-korekty'].includes(v))rev[k]=v;else throw Error('Nieprawidłowa ocena punktu.');}
 const imRev={};for(const [k,v] of Object.entries(d.imageReviews)){if(allowedImages.has(k)&&['nieoceniona','przejrzana-lokalnie','wymaga-korekty'].includes(v))imRev[k]=v;else throw Error('Nieprawidłowa ocena ryciny.');}
 const ev={};for(const [k,v] of Object.entries(d.evidence)){if(!validateKey(k)||!object(v))throw Error('Nieprawidłowa notatka źródłowa.');ev[k]={source:String(v.source||'').slice(0,200),page:String(v.page||'').slice(0,80),note:String(v.note||'').slice(0,1200),date:String(v.date||'').slice(0,100)};}
 if(!confirm('Wczytać audyt? To zastąpi lokalne korekty i notatki; eksportuj obecne dane przed importem.'))return;
 rememberCal464();state.cal=cal;state.reviewMarks=rev;state.imageReviews=imRev;state.evidence=ev;save('gray418_cal',cal);save('gray421_markReviews',rev);save('gray422_imageReviews',imRev);save('gray464_evidence',ev);toast425('Audyt zaimportowany. Dane medyczne atlasu pozostały niezmienione.');render();
 }catch(e){toast425('Nie wczytano: '+String(e.message).slice(0,100))}}
function suggestImage464(){const s=selected();const cur=currentImage();if(!s)return;const options=allImages().filter(im=>point(im,s.id)&&im.id!==cur?.id);const preferred=options.find(im=>im.view===cur?.view&&im.layer===cur?.layer)||options.find(im=>im.view===cur?.view)||options[0];if(!preferred){toast425('Brak przypisanego punktu dla tej struktury w tej okolicy.');return;}state.view=preferred.view||'all';state.layer=preferred.layer||'all';state.imageId=preferred.id;state.zoom=1;syncDepth424(state.layer);render();}
function jumpLayer464(dir){const im=currentImage(),all=allImages();if(!im)return;const deep=['powierzchowna','pośrednia','głęboka'];const ix=deep.indexOf(im.layer);if(ix<0){toast425('Dla tej ryciny nie ma uporządkowanej głębokości warstwy.');return;}const opts=all.filter(v=>v.view===im.view&&deep.includes(v.layer));const candidates=opts.filter(v=>dir>0?deep.indexOf(v.layer)>ix:deep.indexOf(v.layer)<ix).sort((a,b)=>dir*(deep.indexOf(a.layer)-deep.indexOf(b.layer)));if(!candidates.length){toast425('Brak kolejnej dostępnej warstwy w tej samej projekcji.');return;}const target=candidates[0];state.layer=target.layer;state.view=target.view;state.imageId=target.id;state.zoom=1;syncDepth424(state.layer);render();}
