function reviewDashboard464(){const im=currentImage();const st=selected();const ev=evidence464();const marks=Object.keys(DATA.calibration||{}).reduce((n,k)=>n+Object.keys(DATA.calibration[k]||{}).length,0);const active=Object.entries(state.reviewMarks).filter(([k,v])=>v==='wymaga-korekty');const imageFlags=Object.entries(state.imageReviews).filter(([k,v])=>v==='wymaga-korekty');return `<section class="study"><h2>Warsztat kontroli punktów · 4.64</h2><p class="muted">Nie jest to system certyfikacji. Dokumentacja źródłowa i lokalna ocena pozostają odrębne od zweryfikowanej anatomii.</p><div class="auditstats"><span>${marks} historycznych par w bazie</span><span>${active.length} lokalnych zgłoszeń punktów</span><span>${imageFlags.length} zgłoszeń całych rycin</span><span>${Object.keys(state.evidence).length} notatek źródłowych</span></div><div class="button-row"><button class="btn" data-action="exportAudit464">Eksport kompletnego audytu JSON</button><label class="btn" for="auditImport464">Import audytu JSON</label><input id="auditImport464" type="file" accept="application/json,.json" style="max-width:240px"/><button class="btn" data-action="undo464" ${state.auditHistory.length?'':'disabled'}>↶ Cofnij korektę</button><button class="btn" data-action="redo464" ${state.auditRedo.length?'':'disabled'}>↷ Ponów</button></div><h3>Źródło punktu — aktualny wybór</h3><div class="note">${st&&im?`<b>${esc(st.pl)}</b> na rycinie <b>${esc(im.id)}</b>`:'Zaznacz strukturę w atlasie, a następnie otwórz ten warsztat.'}</div><div class="evidence-grid"><label>Źródło (np. Gray, Sobotta)<input id="evSource464" value="${esc(ev.source)}" maxlength="200" placeholder="Pełna nazwa materiału"/></label><label>Strona / rycina<input id="evPage464" value="${esc(ev.page)}" maxlength="80" placeholder="np. tom 1, strona PDF 239"/></label><label class="span2">Obserwacja, rozbieżność lub plan korekty<textarea id="evNote464" maxlength="1200" rows="4" placeholder="Co sprawdzić na tej rycinie?">${esc(ev.note)}</textarea></label></div><button class="btn" data-action="saveEvidence464" ${st&&im?'':'disabled'}>Zapisz notatkę</button><h3>Kolejka wymagających korekty</h3><div class="auditflags">${active.length?active.slice(0,80).map(([k])=>`<button data-auditmark="${esc(k)}">⚑ ${esc(k)}</button>`).join(''):'<p>Brak zgłoszonych punktów.</p>'}</div><div class="auditflags">${imageFlags.map(([k])=>`<button data-auditimg="${esc(k)}">⚑ Rycina ${esc(k)}</button>`).join('')}</div><p class="note">Przywracanie historii dotyczy współrzędnych zapisanych w bieżącej przeglądarce. Dane nie są wysyłane na serwer.</p></section>`;}

