function structures(id=state.region){const s=regionInfo(id); const list=Array.isArray(s.structures)?s.structures:(s.layers||[]).flatMap(l=>l.structures||[]);const out=[];const seen=new Set();for(const it of list){if(it?.id&&!seen.has(it.id)){seen.add(it.id);out.push(it)}}return out;}
function allImages(id=state.region){const base=baseRegion(id), a=DATA.images[base]||(DATA.other[base]||{}).images||[];return a.filter(im=>DATA.assets[im.id]);}
