function readLink425(){try{const raw=location.hash.slice(1);const p=new URLSearchParams(raw);const r=p.get('r');if(!r||!validRegion425.has(r))return;state.region=r;state.view=views.some(x=>x[0]===p.get('v'))?p.get('v'):'all';state.layer=layers.some(x=>x[0]===p.get('l'))?p.get('l'):'all';const found=allImages(r).find(im=>im.id===p.get('i'));if(found){state.imageId=found.id;state.view=found.view||'all';state.layer=found.layer||'all';}else state.imageId=allImages(r)[0]?.id||null;const id=p.get('s');if(id&&structures(r).some(x=>x.id===id))state.selected=id;}catch(e){}}
