function favorite(id){if(state.favorites.has(id))state.favorites.delete(id);else state.favorites.add(id);save('gray418_fav',[...state.favorites]);render();}
function editClick(e){if(!state.editPoint||!state.selected||!currentImage())return;const surf=$('.image-surface');if(!surf)return;const rect=surf.getBoundingClientRect();const ax=(e.clientX-rect.left)/rect.width,ay=(e.clientY-rect.top)/rect.height;if(ax<0||ay<0||ax>1||ay>1)return;const p=point(currentImage(),state.selected);const lx=p?.[2]??Math.min(.7,ax+.07),ly=p?.[3]??Math.max(.07,ay-.12);rememberCal464();state.cal[currentImage().id+'|'+state.selected]=[+ax.toFixed(5),+ay.toFixed(5),lx,ly];save('gray418_cal',state.cal);delete state.reviewMarks[currentImage().id+'|'+state.selected];save('gray421_markReviews',state.reviewMarks);state.editPoint=false;render();}
function exportCSV425(){const rows=[['image_id','structure_id','pl','la','x_anchor','y_anchor','x_label','y_label','point_review','image_review','source']];for(const [region,images] of Object.entries(DATA.images)){for(const im of images){for(const s of structures(region)){const p=point(im,s.id);if(!p)continue;rows.push([im.id,s.id,s.pl||'',s.la||'',...p,reviewStatus(im.id+'|'+s.id),imageReviewStatus(im.id),state.cal[im.id+'|'+s.id]?'local-manual':'atlas-orientational'])}}}
 const csv=rows.map(cols=>cols.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');const u=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'}));a.href=u;a.download='gray444_kontrola_punktow.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}

function exportCorrections(){const content=JSON.stringify({atlas:'4.44',status:'manual-review—not-atlas-verified',marks:state.cal,reviewFlags:state.reviewMarks,imageReviewFlags:state.imageReviews,exportedAt:new Date().toISOString()},null,2);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type:'application/json'}));a.download='gray421_korekty_i_audyt_oznaczen.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
function resetPoint(){const im=currentImage();if(!im||!state.selected)return;if(!(im.id+'|'+state.selected in state.cal))return;rememberCal464();delete state.cal[im.id+'|'+state.selected];save('gray418_cal',state.cal);delete state.reviewMarks[im.id+'|'+state.selected];save('gray421_markReviews',state.reviewMarks);render();}
function reviewKey(){const im=currentImage(),s=selected();return im&&s?im.id+'|'+s.id:null}
function reviewStatus(key){return key?state.reviewMarks[key]||'nieoceniony':'nieoceniony'}
function setReviewStatus(value){const key=reviewKey();if(!key)return;if(!['nieoceniony','wymaga-korekty','przejrzano-lokalnie'].includes(value))return;if(value==='nieoceniony')delete state.reviewMarks[key];else state.reviewMarks[key]=value;save('gray421_markReviews',state.reviewMarks);render()}
function reviewLabel(value){return {'nieoceniony':'Nie oceniono poprawności punktu','wymaga-korekty':'Zgłoszono do korekty','przejrzano-lokalnie':'Przejrzano lokalnie — nie oznacza walidacji atlasowej'}[value]||'Nie oceniono'}
function imageReviewStatus(id){return state.imageReviews[id]||'nieoceniona'}
function imageReviewLabel(id){return {'nieoceniona':'Nieoceniona lokalnie','wymaga-korekty':'Zgłoszono problem z ryciną','przejrzana-lokalnie':'Przejrzana lokalnie (NIE zweryfikowana atlasowo)'}[imageReviewStatus(id)]||'Nieoceniona lokalnie'}
function setImageReview(v){const im=currentImage();if(!im||!['nieoceniona','wymaga-korekty','przejrzana-lokalnie'].includes(v))return;if(v==='nieoceniona')delete state.imageReviews[im.id];else state.imageReviews[im.id]=v;save('gray422_imageReviews',state.imageReviews);render()}
function regionForImage(id){return Object.keys(DATA.images).find(r=>(DATA.images[r]||[]).some(x=>x.id===id))||'shoulder_atlas'}
function gotoReviewedImage(id){navigate(regionForImage(id));imageById(id)}
function imgPalette(s){return cats[s?.cat]||'#61baff'}
function marker(im,s){const p=point(im,s.id);if(!p)return '';const [ax,ay,lx,ly]=p;const x=ax*1000,y=ay*1000,px=lx*1000,py=ly*1000;const col=reviewStatus(im.id+'|'+s.id)==='wymaga-korekty'?'#ffb762':imgPalette(s);const dashed=reviewStatus(im.id+'|'+s.id)==='wymaga-korekty'?' stroke-dasharray="9 7"':'';const risk=TRIAGE454[im.id+'|'+s.id]?.risk||'nieznany';const line=`<path d="M${px} ${py} L${x} ${y}" fill="none" stroke="${col}" stroke-width="3"${dashed}/><circle cx="${x}" cy="${y}" r="23" fill="${col}" fill-opacity=".12" stroke="${col}" stroke-opacity=".75" stroke-width="2"/><circle cx="${x}" cy="${y}" r="10" fill="${col}" stroke="#fff" stroke-width="3"/>`;const callx=Math.max(4,Math.min(96,lx*100)),cally=Math.max(7,Math.min(92,ly*100));const callside=lx>.59?'right':'left';return `<svg class="marker-overlay" viewBox="0 0 1000 1000" preserveAspectRatio="none">${line}</svg><div class="callout" style="${callside==='right'?'right:'+(100-callx)+'%':'left:'+callx+'%'};top:${cally}%;border-color:${col}"><b>${esc(s.pl)}</b><em>${esc(s.la||s.en||'')}</em><small class="mark-cert">${esc(state.cal[im.id+'|'+s.id]?'Lokalna korekta — niezweryfikowana':'Punkt orientacyjny · sprawdź w atlasie')} · priorytet: ${esc(risk)}</small></div>`;}
function allMarkerDots(im){const pool=state.spotMode?spotCandidates():mapped(im).filter(s=>!state.showOnlySafe||safeMark464(im,s));return `<svg class="marker-overlay" viewBox="0 0 1000 1000" preserveAspectRatio="none">${pool.map(s=>{const p=point(im,s.id);const color=imgPalette(s);return `<circle class="hotspot" data-struct="${esc(s.id)}" cx="${p[0]*1000}" cy="${p[1]*1000}" r="11" stroke="#fff" stroke-width="3" fill="${color}"/>`}).join('')}</svg>`;}
function plate(){const im=currentImage();if(!im)return `<div class="empty"><h3>Brak ryciny dla tej kombinacji</h3><p>Wybrany widok i warstwa nie występują razem w tej okolicy. Zmień tylko jeden z filtrów lub wyświetl wszystkie.</p><button class="btn" data-action="clearFilters">Pokaż wszystkie dostępne ryciny</button></div>`;
const s=selected(), overlay=state.showLabels&&s&&!state.spotMode&&(!state.showOnlySafe||safeMark464(im,s))?marker(im,s):'', dots=(state.showDots||state.spotMode)?allMarkerDots(im):'';
return `<div class="audit-flag">${AUDIT[im.id]?.status==='wstępna-kontrola-topografii'?'Wstępna kontrola topografii · rycina nadal wymaga weryfikacji szczegółów':'Rycina niezweryfikowana anatomicznie · znaczniki orientacyjne'} · ${esc(imageReviewLabel(im.id))}</div><div class="plate-zoom" style="transform:scale(${state.zoom})"><div class="image-surface"><img class="plate-image" src="${esc(imageURL(im))}" alt="${esc(im.title)}" decoding="async"/>${dots}${overlay}</div></div>${state.editPoint?'<div class="marker-edit">Tryb korekty: kliknij właściwe miejsce struktury na obrazie</div>':''}`;}
function findTabText(s,tab){if(!s)return '';const det=Object.entries(s.details||{});const keys={Przyczepy:['przyczep','poczatek','początek','koniec'],Czynność:['czynno','funkcj','rola'],Unerwienie:['unerw'],Unaczynienie:['unaczyn','tetnic','tętnic'],Klinika:['klinik','znaczenie']};if(tab==='Opis')return s.summary||'Dla tej struktury nie dodano opisu.';let hits=det.filter(([k])=>(keys[tab]||[]).some(needle=>norm(k).includes(norm(needle)))).map(([k,v])=>`${k}: ${v}`);return hits.join('\n')||'W obecnej bazie nie ma potwierdzonych danych do tej zakładki.';}
function relatedImages(){const s=selected();return (s?allImages().filter(im=>point(im,s.id)):images()).slice(0,8);}
function menuHTML(){const imageId=id=>allImages(id)[0];const item=id=>{const im=imageId(id);return `<button class="navitem ${state.region===id?'active':''}" data-region="${esc(id)}">${im?`<img class="navthumb" loading="lazy" src="${esc(thumbnailURL(im))}" alt=""/>`:''}<span>${esc(titleOf(id))}</span></button>`};return `<div class="navtitle">Układy anatomiczne <span>⌄</span></div><div class="tree">${allRegions.map((g,i)=>`<details ${i===0?'open':''}><summary>${esc(g.group)}</summary><div class="tree-group">${g.items.map(([t,ids])=>`<details ${ids.includes(state.region)?'open':''}><summary>${esc(t)}</summary><div class="tree-group">${ids.map(item).join('')}</div></details>`).join('')}</div></details>`).join('')}</div><div class="sidebar-note">Atlas zachowuje wcześniejsze obrazy. Strzałki z poprzednich wersji są <b>orientacyjne</b> — obraz o wysokiej szczegółowości sam w sobie nie potwierdza dokładności anatomicznej.</div>`;}
function headerHTML(){return `<div class="brand"><span class="brand-symbol">A</span><div><div class="brand-title">Anatomia z Graya <span style="color:#5cbaff">4.64</span></div><div class="brand-sub">Interaktywny atlas · warstwy · struktury · nauka</div></div></div><nav class="topnav" aria-label="Moduły"><button class="${state.tab==='atlas'?'active':''}" data-tab="atlas"><span class="ico">▣</span>Atlas</button><button class="${state.tab==='quiz'?'active':''}" data-tab="quiz"><span class="ico">◈</span>Quiz</button><button class="${state.tab==='cards'?'active':''}" data-tab="cards"><span class="ico">▤</span>Fiszki</button><button class="${state.tab==='favorites'?'active':''}" data-tab="favorites"><span class="ico">☆</span>Ulubione</button><button class="${state.tab==='notes'?'active':''}" data-tab="notes"><span class="ico">✎</span>Notatki</button><button class="${state.tab==='audit'?'active':''}" data-tab="audit"><span class="ico">✓</span>Audyt rycin</button><button class="${state.tab==='quality444'?'active':''}" data-tab="quality444"><span class="ico">⊕</span>Kontrola 4.54</button><button class="${state.tab==='triage454'?'active':''}" data-tab="triage454"><span class="ico">⚑</span>Priorytety</button><button class="${state.tab==='work464'?'active':''}" data-tab="work464"><span class="ico">⌁</span>Warsztat</button><button class="${state.tab==='lab3d'?'active':''}" data-tab="lab3d"><span class="ico">◈</span>3D — laboratorium</button><button class="${state.tab==='help'?'active':''}" data-tab="help"><span class="ico">⚙</span>Pomoc</button></nav><div class="top-search"><span>⌕</span><input id="globalSearch" type="search" value="${esc(state.globalQuery)}" placeholder="Szukaj struktury PL / LA / EN..." autocomplete="off"/></div>${state.searchOpen&&state.globalQuery.trim()?searchHTML():''}`;}
function findGlobal(q){const all=[];const seen=new Set();for(const reg of [...DATA.atlas.map(x=>x.id),...DATA.extra.map(x=>x.id)])for(const s of structures(reg)){const key=reg+'|'+s.id;if(seen.has(key))continue;seen.add(key);if([s.pl,s.la,s.en].some(x=>norm(x).includes(norm(q))))all.push({region:reg,s});}return all.slice(0,20);}
function searchHTML(){const hits=findGlobal(state.globalQuery);return `<div class="searchresults">${hits.length?hits.map(r=>`<button class="searchresult" data-search-region="${r.region}" data-search-id="${esc(r.s.id)}">${esc(r.s.pl)} <small>${esc(r.s.la||'')} · ${esc(titleOf(r.region))}</small></button>`).join(''):'<div class="empty" style="padding:20px">Nie znaleziono struktury.</div>'}</div>`;}
function toggleLabelsUI(){state.showLabels=!state.showLabels;render();}
function viewerHTML(){const im=currentImage(), m=im?mapped(im):[];return `<div class="viewer"><div class="viewer-top"><div><h2>${esc(titleOf(state.region))}</h2><small>${im?esc(im.title):'Brak ryciny'}</small></div><div class="viewer-tools"><button class="icon-btn" data-action="minus" title="Oddal">−</button><button class="icon-btn" data-action="resetZoom" title="Reset przybliżenia">100%</button><button class="icon-btn" data-action="plus" title="Przybliż">+</button><button class="icon-btn ${state.showLabels?'active':''}" data-action="labels">Etykiety</button><button class="icon-btn ${state.showOnlySafe?'active':''}" data-action="safeOnly464" title="Ukrywa zgłoszone do korekty punkty; nie oznacza pozostałych jako zweryfikowane">Ukryj zgłoszone</button><button class="icon-btn ${state.showDots?'active':''}" data-action="dots">Punkty</button><button class="icon-btn" data-action="prevMarked464" title="Poprzednia oznaczona struktura">← Struktura</button><button class="icon-btn" data-action="nextMarked464" title="Następna oznaczona struktura">Struktura →</button><button class="icon-btn ${state.spotMode?'active':''}" data-action="spotMode">${state.spotMode?'Zakończ trening':'Trening lokalizacji'}</button><button class="icon-btn" data-action="fullscreen">⛶</button></div></div>${state.spotMode?`<div class="spotquiz"><b>${state.spotTarget?`Wskaż na rycinie: ${esc(structures().find(x=>x.id===state.spotTarget)?.pl||'strukturę')}`:'Na tej rycinie potrzeba co najmniej dwóch oznaczonych struktur do treningu.'}</b><span>Wynik: ${state.spotScore} / ${state.spotTotal} · punkty orientacyjne, nie w pełni zweryfikowane.</span>${state.spotAnswer?`<span class="${state.spotAnswer===state.spotTarget?'spotgood':'spotbad'}">${state.spotAnswer===state.spotTarget?'Poprawnie!':'Nie — zaznaczono '+esc(structures().find(x=>x.id===state.spotAnswer)?.pl||state.spotAnswer)}.</span><button class="btn" data-action="spotNext">Następna struktura</button>`:''}</div>`:''}<div class="plate-viewport" id="plateViewport">${plate()}</div>${im?`<div class="figure-qc"><div><strong>Kontrola ryciny:</strong> <span>${esc(imageReviewLabel(im.id))}</span><small>Ocena lokalna nie oznacza weryfikacji atlasowej.</small></div><div class="figure-qc-buttons"><button class="btn ${imageReviewStatus(im.id)==='wymaga-korekty'?'active':''}" data-action="imageFlag">⚑ Błąd na rycinie</button><button class="btn ${imageReviewStatus(im.id)==='przejrzana-lokalnie'?'active':''}" data-action="imageSeen">✓ Przejrzano</button><button class="btn" data-action="imageClear">Wyczyść</button></div></div>`:''}<div class="stage-warning">${im?`<b>${m.length}</b> punktów orientacyjnych · <b>${im?mappingStats425(im).flagged:0}</b> zgłoszonych do korekty. `:'Brak ryciny dla wybranych filtrów. '}${selected()&&!point(im,selected().id)?'Wybrana struktura nie ma skalibrowanego wskazania na tej rycinie — nie wyświetlam przypadkowej strzałki.':'Kliknij nazwę lub punkt, aby otworzyć opis.'} <span style="color:#97b3cd">Zmieniaj projekcję i warstwę niezależnie.</span></div>${state.compare!=='off'?compareHTML():''}</div>`;}
function compareHTML(){const options=allImages().filter(im=>im.id!==currentImage()?.id);const chosen=options.find(x=>x.id===state.compareId)||options[0];if(!chosen)return `<div class="compare-panel">Brak drugiej ryciny do porównania.</div>`;return `<div class="compare-panel"><div class="compare-controls"><b>Porównanie rycin:</b><select id="compareId">${options.map(im=>`<option value="${esc(im.id)}" ${chosen.id===im.id?'selected':''}>${esc(im.title.slice(0,65))}</option>`).join('')}</select><button class="btn ${state.compare==='side'?'active':''}" data-action="compareSide">Obok siebie</button><button class="btn ${state.compare==='overlay'?'active':''}" data-action="compareOverlay">Przenikanie</button>${state.compare==='overlay'?`<label>Widoczność drugiej <input id="opacity" type="range" min="0" max="100" value="${state.opacity}"/></label>`:''}</div>${state.compare==='side'?`<div class="compare-grid"><img src="${esc(imageURL(currentImage()))}" alt="Pierwsza rycina"/><img src="${esc(imageURL(chosen))}" alt="Druga rycina"/></div>`:`<div class="compare-overlay"><img src="${esc(imageURL(currentImage()))}"/><img id="compareSecond" src="${esc(imageURL(chosen))}" style="opacity:${state.opacity/100}"/></div>`}<div class="note">To niezależne ilustracje, a nie geometrycznie zarejestrowane warstwy tego samego preparatu. Przenikanie służy jedynie do porównania.</div></div>`;}
function inspectorHTML(){const s=selected(),im=currentImage(),m=im?mapped(im):[],filtered=structures().filter(st=>[st.pl,st.la,st.en].some(n=>norm(n).includes(norm(state.filters))));const rel=relatedImages();return `<aside class="detail"><div class="top">STRUKTURA</div><section class="section">${s?`<div style="display:flex;align-items:start;justify-content:space-between;gap:7px"><div><h3>${esc(s.pl)}</h3><div class="latin">${esc(s.la)}</div><div class="english">${esc(s.en)}</div></div><button class="icon-btn ${state.favorites.has(s.id)?'active':''}" data-action="fav" title="Dodaj do ulubionych">${state.favorites.has(s.id)?'★':'☆'}</button></div>${meshForStruct(s.id)?`<div class="mesh-bridge-info"><button class="btn" data-action="bridge3d">◈ Otwórz w 3D — model poglądowy</button><small>Ta sama nazwa w bazie; geometria siatki 3D nie została zweryfikowana anatomicznie.</small></div>`:''}<div class="tabs">${['Opis','Przyczepy','Czynność','Unerwienie','Unaczynienie','Klinika'].map(t=>`<button data-detail-tab="${t}" class="${state.detailTab===t?'active':''}">${t}</button>`).join('')}</div><div class="details-text">${esc(findTabText(s,state.detailTab)).replace(/\n/g,'<br/>')}</div><div class="statusbar"><span class="tag ${point(im,s.id)?'':'warn'}">${point(im,s.id)?'Punkt orientacyjny na rycinie':'Brak punktu na tej rycinie'}</span>${!point(im,s.id)?`<button class="btn" data-action="suggestImage464">Pokaż rycinę z oznaczeniem (zmieni filtr)</button>`:""}${state.cal[im?.id+'|'+s.id]?'<span class="tag">Lokalna korekta</span>':''}</div><div class="pointreview"><strong>Kontrola oznaczenia — tylko lokalna</strong><div class="pointreview-actions"><button class="btn ${reviewStatus(reviewKey())==='wymaga-korekty'?'active':''}" data-action="reviewFlag">⚑ Wymaga korekty</button><button class="btn ${reviewStatus(reviewKey())==='przejrzano-lokalnie'?'active':''}" data-action="reviewSeen">✓ Przejrzano</button><button class="btn" data-action="reviewClear">Wyczyść ocenę</button></div><small>${esc(reviewLabel(reviewStatus(reviewKey())))}. Samodzielna ocena nie stanowi weryfikacji względem atlasu.</small></div><div class="aux" style="margin-top:11px"><button class="btn ${state.editPoint?'active':''}" data-action="editPoint">${state.editPoint?'Anuluj korektę':'Popraw punkt'}</button><button class="btn" data-action="resetPoint">Przywróć</button><button class="btn" data-action="copyPoint444">Współrzędne punktu</button><button class="btn" data-tab="work464">Notatka źródłowa</button><button class="btn" data-action="export">Eksport JSON</button></div>`:'<div class="note">Wybierz strukturę z listy lub kliknij punkt na rycinie.</div>'}</section><section class="section"><div class="struct-head"><span>STRUKTURY W OKOLICY (${filtered.length})</span><span>${m.length} z oznaczeniem</span></div><input class="list-filter" id="structFilter" value="${esc(state.filters)}" placeholder="Filtruj polskie, łacińskie i angielskie nazwy"/><div class="struct-list">${filtered.length?filtered.map(st=>`<button class="struct-item ${st.id===state.selected?'active':''}" data-struct="${esc(st.id)}"><span class="names"><b>${esc(st.pl)}</b><small>${esc(st.la||st.en||'')}</small></span><span class="dot ${reviewStatus(im?.id+'|'+st.id)==='wymaga-korekty'?'warn-dot':point(im,st.id)?'yes':''}" title="${reviewStatus(im?.id+'|'+st.id)==='wymaga-korekty'?'Wymaga korekty':point(im,st.id)?'Oznaczenie orientacyjne':'Bez oznaczenia'}"></span></button>`).join(''):'<div class="note">Nie znaleziono struktur.</div>'}</div></section><section class="section"><details open><summary>Ryciny z oznaczeniem wybranej struktury</summary><div class="related-images">${rel.length?rel.map(x=>`<button class="rel" data-image="${esc(x.id)}"><img loading="lazy" src="${esc(thumbnailURL(x))}"/><small>${esc(x.title)}</small></button>`).join(''):'<div class="note">Brak powiązanych rycin.</div>'}</div></details></section><div class="note">Oznaczenia automatyczne i ręczne wymagają osobnej kontroli topograficznej. Status „przejrzano” nie oznacza weryfikacji atlasowej. Korekta wykonana przez użytkownika nie staje się automatycznie oznaczeniem zweryfikowanym.</div></aside>`;}
function toolbarHTML(){const ims=allImages();const availViews=new Set(ims.map(x=>x.view));const availLayers=new Set(ims.map(x=>x.layer));return `<div class="trail"><span>Atlas</span><span class="sep">›</span><strong>${esc(titleOf(state.region))}</strong><span class="sep">›</span><span>${state.view==='all'?'Wszystkie projekcje':state.view}</span><span class="sep">›</span><span>${state.layer==='all'?'Wszystkie warstwy':state.layer}</span></div><div class="control-row"><span class="control-key">WIDOK</span>${views.map(([key,name])=>`<button data-view="${key}" ${key!=='all'&&!availViews.has(key)?'disabled':''} class="${state.view===key?'active':''}">${name}</button>`).join('')}<span class="control-key">WARSTWA</span>${layers.filter(([key])=>key==='all'||availLayers.has(key)).map(([key,name])=>`<button data-layer="${key}" class="${state.layer===key?'active':''}">${name}</button>`).join('')}<button data-action="shallowLayer464" title="Poprzednia warstwa w tej samej projekcji">↑ Płycej</button><button data-action="deepLayer464" title="Kolejna warstwa w tej samej projekcji">↓ Głębiej</button><button data-action="clearFilters">Reset filtrów</button><button class="push" type="button" data-action="showDock424">◈ Otwórz podgląd 3D</button><button type="button" data-action="share425" title="Skopiuj link do bieżącej ryciny">↗ Udostępnij widok</button><button class="push ${state.compare!=='off'?'active':''}" data-action="toggleCompare">${state.compare!=='off'?'Zamknij porównanie':'Porównaj ryciny'}</button></div>`;}
function galleryHTML(){const ims=images(),im=currentImage();return `<div class="gallery"><div class="gallery-top"><span>INNE RYCINY W TEJ OKOLICY <small>(${ims.length}; wszystkie dostępne: ${allImages().length})</small></span><span class="muted">Widok i warstwa filtrują galerię niezależnie</span></div><div class="gallery-scroll">${ims.map(x=>`<button class="thumb ${im?.id===x.id?'active':''}" data-image="${esc(x.id)}"><img loading="lazy" src="${esc(thumbnailURL(x))}" alt=""/><span>${esc(x.title)}</span></button>`).join('')||'<div class="note">Brak rycin dla aktywnych filtrów.</div>'}</div></div>`;}
function atlasHTML(){return `${toolbarHTML()}<div class="workbench">${viewerHTML()}${inspectorHTML()}${galleryHTML()}</div><div class="aboutline">Źródła odniesienia: Gray, Sobotta i Rohen–Yokochi (materiały użytkownika). Ryciny są autorskimi wizualizacjami komputerowymi. Nie wszystkie położenia drobnych struktur zostały zweryfikowane względem preparatu fotograficznego.</div>`;}
function bank(){const all=[];const seen=new Set();for(const reg of DATA.atlas)for(const st of structures(reg.id)){if(st.pl&&st.la&&!seen.has(st.id)){seen.add(st.id);all.push(st)}}for(const reg of DATA.extra)for(const st of structures(reg.id)){if(st.pl&&st.la&&!seen.has(st.id)){seen.add(st.id);all.push(st)}}return all;}
const shuffle=a=>a.slice().sort(()=>Math.random()-.5);
function startQuiz(){state.quizMistakes=[];const b=bank();const qs=shuffle(b).slice(0,Math.min(state.quizTotal,b.length));state.quizQuestions=qs.map(s=>({s,choices:shuffle([s,...shuffle(b.filter(x=>x.id!==s.id&&x.la!==s.la&&x.pl!==s.pl)).slice(0,3)]).map(x=>({id:x.id,name:x.la}))}));state.quizIndex=0;state.quizScore=0;state.quizAnswer=null;}
function answer(i){if(state.quizAnswer!==null)return;const q=state.quizQuestions[state.quizIndex];state.quizAnswer=i;if(q.choices[i].id===q.s.id)state.quizScore++;else if(!state.quizMistakes.some(x=>x.id===q.s.id))state.quizMistakes.push(q.s);render();}
function startMistakeQuiz425(){const b=bank();const wrong=state.quizMistakes.slice();state.quizMistakes=[];state.quizQuestions=wrong.map(s=>{const other=shuffle(b.filter(x=>x.id!==s.id)).slice(0,3);return{s,choices:shuffle([s,...other]).map(x=>({id:x.id,name:x.la}))}});state.quizIndex=0;state.quizScore=0;state.quizAnswer=null;}

function quizHTML(){const q=state.quizQuestions[state.quizIndex];if(!q)return `<div class="study"><h2>Quiz ukończony</h2><p>Wynik terminologii: ${state.quizScore} / ${state.quizQuestions.length}</p><div class="button-row" style="margin-top:16px"><button data-action="newQuiz">Nowa sesja</button><button data-tab="cards">Przejdź do fiszek</button>${state.quizMistakes.length?`<button data-action="quizMistakes">Powtórz błędne odpowiedzi (${state.quizMistakes.length})</button>`:''}</div></div>`;const done=state.quizAnswer!==null;return `<div class="study"><div class="aux"><span class="stat">Pytanie ${state.quizIndex+1}/${state.quizQuestions.length}</span><span class="stat">Poprawne: ${state.quizScore}</span><label>Liczba pytań <select id="quizTotal"><option ${state.quizTotal===10?'selected':''}>10</option><option ${state.quizTotal===20?'selected':''}>20</option><option ${state.quizTotal===50?'selected':''}>50</option></select></label></div><div class="progress" style="margin-top:14px"><div style="width:${100*state.quizIndex/state.quizQuestions.length}%"></div></div><h2>Quiz terminologiczny — PL ↔ LA</h2><p class="q">Jaka jest łacińska nazwa struktury: <strong>${esc(q.s.pl)}</strong>?</p><div class="choices">${q.choices.map((c,i)=>`<button class="choice ${done&&c.id===q.s.id?'good':done&&i===state.quizAnswer?'bad':''}" data-answer="${i}" ${done?'disabled':''}>${esc(c.name)}</button>`).join('')}</div>${done?`<div class="note">Poprawna odpowiedź: <b>${esc(q.s.la)}</b>. ${esc(q.s.summary||'')}</div><div class="button-row" style="margin-top:12px"><button data-action="nextQuiz">${state.quizIndex+1===state.quizQuestions.length?'Zobacz wynik':'Następne pytanie'}</button></div>`:''}</div>`;}
function cardsHTML(){const b=bank();const s=b[state.flashIndex%b.length];if(!s)return '<div class="empty">Brak fiszek.</div>';return `<div class="study"><h2>Fiszki · anatomia</h2><p class="muted">Fiszka ${state.flashIndex+1} / ${b.length} · kliknij kartę, aby odsłonić tłumaczenie</p><div class="flash" data-action="flip">${state.flashFlip?`<div><b>${esc(s.la)}</b><div class="flash-answer">${esc(s.en||'')}<br/>${esc(s.summary||'')}</div></div>`:`<b>${esc(s.pl)}</b>`}</div><div class="button-row"><button data-action="prevCard">← Poprzednia</button><button data-action="flip">Odwróć</button><button data-action="nextCard">Następna →</button></div></div>`;}
function favHTML(){const b=bank().filter(st=>state.favorites.has(st.id));return `<div class="study"><h2>☆ Ulubione struktury</h2><p class="muted">Zapisane w tej przeglądarce.</p><div class="micro-grid">${b.length?b.map(st=>`<div class="micro-card"><h3>${esc(st.pl)}</h3><p>${esc(st.la)} · ${esc(st.en)}</p><p>${esc(st.summary||'')}</p><div class="button-row" style="margin-top:12px"><button data-favopen="${esc(st.id)}">Otwórz w atlasie</button></div></div>`).join(''):'<div class="note">Dodaj strukturę gwiazdką w panelu atlasu.</div>'}</div></div>`;}
function notesHTML(){const s=selected();return `<div class="study"><h2>Notatki do anatomii</h2><p class="muted">Zapis lokalny w przeglądarce. Notatki są przypisywane do aktywnej okolicy i wybranej struktury.</p><p style="margin:12px 0"><b>${esc(titleOf(state.region))}</b>${s?' · '+esc(s.pl):''}</p><textarea class="text-editor" id="noteText" placeholder="Notatki do tej struktury lub okolicy...">${esc(state.notes[state.region+'|'+(state.selected||'region')]||'')}</textarea><div class="button-row" style="margin-top:10px"><button data-action="saveNote">Zapisz notatkę</button><button data-action="exportNotes">Eksportuj notatki</button><button data-tab="atlas">Wróć do atlasu</button></div></div>`;}
function helpHTML(){return `<div class="study"><h2>Jak korzystać z atlasu 4.54</h2><div class="micro-grid"><div class="micro-card"><h3>Widok ≠ warstwa</h3><p>Wybierz kierunek oglądania i głębokość preparowania osobno. Aplikacja nie podmienia automatycznie widoku tylnego za warstwę głęboką.</p></div><div class="micro-card"><h3>Oznaczenia na ilustracjach</h3><p>Po wybraniu struktury wskazanie pojawia się wyłącznie na obrazie, do którego zostało przypisane. Brak punktu jest wyraźnie komunikowany.</p></div><div class="micro-card"><h3>Porównanie rycin</h3><p>Tryb obok siebie służy do rzeczywistego porównania dwóch ujęć. Przenikanie przezroczystością nie oznacza geometrycznie zarejestrowanych warstw.</p></div><div class="micro-card"><h3>Poprawa wskazań</h3><p>Wybierz strukturę, użyj „Popraw punkt”, kliknij prawidłowe miejsce na obrazie. Korekty są zapisywane tylko lokalnie i można je wyeksportować.</p></div></div><div class="note"><b>Źródło quizu:</b> gra terminologiczna korzysta z nazw w bazie aplikacji. Wynik quizu nie jest oceną znajomości rzeczywistej topografii. </div><div class="note">Brak pełnego, zweryfikowanego modelu 3D. Ryciny komputerowo wygenerowane mogą zawierać błędy anatomii, dlatego wymagają konfrontacji z Grayem, Sobotą i atlasem fotograficznym Rohena–Yokochiego.</div></div>`;}

function reviewHTML(){
 const figures=Object.entries(AUDIT);const n=figures.length;const flagged=Object.entries(state.reviewMarks).filter(([,v])=>v==='wymaga-korekty');const locallySeen=Object.values(state.reviewMarks).filter(v=>v==='przejrzano-lokalnie').length;const checked=figures.filter(([,m])=>m.status==='wstępna-kontrola-topografii');const imgFlagged=Object.keys(state.imageReviews).filter(id=>state.imageReviews[id]==='wymaga-korekty');const imgSeen=Object.keys(state.imageReviews).filter(id=>state.imageReviews[id]==='przejrzana-lokalnie');const notes=[
 ['bark_tyl_418','Bark tylny: podgrzebieniowy / obły większy', 'Porównanie topograficzne: Sobotta tom 1 PDF s. 239; Gray tom 1 rozdz. kończyna górna.'],
 ['bark_pacha_418','Dół pachowy: naczynia / splot', 'Porównanie regionalne: Gray tom 1 PDF s. 393; Sobotta PDF s. 239. Gałęzie naczyń niezweryfikowane.'],
 ['przedramie_tyl_418','Przedramię grzbietowe', 'Porównanie: Sobotta tom 1 PDF s. 202; Rohen–Yokochi PDF s. 287. Widok tylny ≠ warstwa głęboka.'],
 ['dłon_palm_418','Dłoń: kłąb / kłębik / łuk dłoniowy','Porównanie: Sobotta tom 1 PDF s. 250; Rohen–Yokochi PDF s. 287. Przebieg łuku wymaga kontroli.']];
 return `<section class="study"><h2>Audyt anatomiczny · wersja 4.64</h2><p class="muted">Rejestr obejmuje wszystkie ${n} plików. Automatyczna kontrola kompletności NIE jest weryfikacją anatomiczną. Wstępny przegląd obejmuje ${checked.length} plansz; żadnej z 96 nie oznaczono jako pełną rekonstrukcję zweryfikowaną atlasowo.</p><div class="auditstats"><span>${n} plików graficznych</span><span>${checked.length} wstępnie obejrzanych topograficznie</span><span>${n-checked.length} oczekuje na przegląd</span><span>104 mapowania czynne · 7 zarchiwizowanych · 35 osieroconych zarchiwizowano · miniatury WebP</span></div><div class="note"><b>Ważna reguła:</b> dla jednej ryciny osobno oceniamy (1) nazwy i przynależność do warstw, (2) położenie strzałki, (3) realność narysowanej struktury, (4) relacje z sąsiadami. Hiperrealizm wizualny nie potwierdza dokładności.</div><h3>Lokalna kontrola całych rycin</h3><p class="muted">Zgłoszono ${imgFlagged.length} rycin do korekty; ${imgSeen.length} przejrzano lokalnie. Żadna z ocen nie oznacza formalnej walidacji anatomicznej.</p><div class="auditflags">${imgFlagged.length?imgFlagged.map(id=>`<button data-auditimg="${esc(id)}">⚑ ${esc(id)}</button>`).join(''):'<small>Brak zgłoszeń dotyczących całych rycin.</small>'}</div><h3>Twoje lokalne oceny wskazań</h3><p class="muted">${flagged.length} punktów zgłoszonych do korekty · ${locallySeen} punktów przejrzanych lokalnie. Nie są to wyniki formalnej weryfikacji atlasowej.</p><div class="auditflags">${flagged.length?flagged.map(([key])=>{const split=key.split('|');const im=split[0],st=split.slice(1).join('|');return `<button data-auditmark="${esc(im)}|${esc(st)}">⚑ ${esc(im)} · ${esc(st)}</button>`}).join(''):'<small>Nie zgłoszono jeszcze punktów do korekty.</small>'}</div><div class="button-row" style="margin:10px 0"><button data-action="export">Eksportuj korekty (JSON)</button><button data-action="exportCSV">Eksportuj listę oznaczeń (CSV)</button></div><h3>Przejrzane obrazy i problemy</h3><div class="auditcards">${notes.map(([id,title,desc])=>`<div class="auditcard"><img src="${esc(thumbnailURL(id))}" alt="${esc(title)}" loading="lazy"/><div><h4>${esc(title)}</h4><p>${esc(desc)}</p><p>${esc(AUDIT[id]?.review?.warning||'')}</p><button data-auditimg="${esc(id)}">Otwórz w atlasie</button></div></div>`).join('')}</div><h3>Rejestr wszystkich rycin</h3><p class="muted">Każda plansza ma własny identyfikator, status i liczbę punktów. Zidentyfikowano duplikaty. Włączono do galerii cztery wcześniej niepodłączone ryciny. Zachowano osobno 35 dawnych wskazań do nieistniejących identyfikatorów obrazów.</p><div class="auditgrid">${figures.map(([id,f])=>`<div class="auditentry"><img src="${esc(thumbnailURL(id))}" alt="" loading="lazy"/><div><b>${esc(id)}</b><small>${f.status==='wstępna-kontrola-topografii'?'Wstępnie obejrzana topografia':'Niezweryfikowana anatomicznie'}</small><small>${esc(imageReviewLabel(id))}</small><button data-auditimg="${esc(id)}" class="mini-review-open">Otwórz rycinę</button><small>${f.width}×${f.height} · mapy punktów: ${f.markCount}</small>${f.duplicates.length?`<small>Tożsame pliki: ${esc(f.duplicates.join(', '))}</small>`:''}</div></div>`).join('')}</div><div class="note">Źródła prywatnie porównane: Gray tom 1 (m.in. PDF s. 393), Sobotta tom 1 (PDF ss. 202, 239, 250), Rohen–Yokochi (PDF s. 287). Atlasów komercyjnych nie włączono do publicznej paczki.</div></section>`;
}
function lab3DHTML(){return `<section class="study"><h2>Laboratorium modeli 3D · import GLB</h2><p class="muted">Laboratorium 3D: WebGL2 lub zapasowy renderer Canvas 2D. Zaimportuj własny nieskompresowany GLB 2.0, obracaj, zaznaczaj i ukrywaj siatki. Domyślny model 20 siatek jest wyłącznie poglądowym modelem relacji przestrzennych, nie modelem o zatwierdzonej topografii. Importowany model nie staje się automatycznie zweryfikowanym atlasem.</p><div class="lab-bridge">${state.bridgeMesh?`<p>Otworzono model z atlasu: <b>${esc(state.bridgeMesh)}</b>. Zostanie zaznaczona odpowiadająca mu siatka demonstracyjna.</p>`:'<p>Wybierz siatkę w 3D. Jeśli ma odpowiednik 2D, możesz wrócić do ryciny anatomicznej.</p>'}<button class="btn" data-action="bridgeBack" ${state.bridgeFrom3D||state.bridgeReturn?'':'disabled'}>← Otwórz w atlasie 2D</button><span>${state.bridgeFrom3D?`Wybrano siatkę: ${esc(state.bridgeFrom3D)}`:'Powiązanie jest tylko semantyczne (nazwa struktury); brak rejestracji geometrycznej 2D↔3D.'}</span></div><iframe id="lab3dframe"
 title="Laboratorium 3D — prototyp anatomiczny" src="model3d_lab.html" style="width:100%;height:840px;border:1px solid #274663;border-radius:15px;background:#081a2d"></iframe><div class="note">Dalszy plan: pozyskać wyraźnie licencjonowane siatki prawdziwych struktur (np. BodyParts3D), przypisać identyfikatory terminologii anatomicznej, porównać z atlasami, sprawdzić granice i punkty przyczepów oraz dopiero później podpiąć interaktywny atlas 3D.</div></section>`;}

function quality444(){const im=currentImage();const marks=im?mapped(im):[];const issues=marks.filter(x=>reviewStatus(im.id+'|'+x.id)==='wymaga-korekty');return `<section class="study"><h2>Kontrola jakości · aktualizacja 4.64</h2><p class="muted">Wersja 4.54 nie uznaje żadnej ryciny generatywnej za w pełni zweryfikowaną atlasowo. Przegląd topografii 6 plansz był wstępny; pozostałe oczekują na dokładną ocenę.</p><div class="auditstats"><span>96 rycin zachowanych</span><span>104 czynne mapy + 7 zarchiwizowanych</span><span>6 rycin wstępnie obejrzanych</span><span>20 siatek 3D — geometria poglądowa</span></div><h3>Aktywna rycina: ${esc(im?.title||'brak')}</h3><div class="note">${im?`ID: ${esc(im.id)} · orientacyjne wskazania: ${marks.length} · lokalne zgłoszenia: ${issues.length}`:'Wybierz rycinę w atlasie.'}</div><div class="button-row"><button class="btn" data-tab="audit">Otwórz pełny rejestr rycin</button><button class="btn" data-action="exportCSV">Eksport punktów CSV</button><button class="btn" data-tab="lab3d">Przejdź do 3D</button></div><h3>Wyniki automatycznej kontroli</h3><p class="note">Narzędzia służą do wykrywania problemów z danymi i ich lokalizacją, nie do formalnego zatwierdzania rycin.</p><p>Sprawdzono istnienie plików i poprawność znormalizowanych współrzędnych. Kontrola matematyczna <strong>nie</strong> potwierdza poprawności wskazania na ciele.</p><h3>Priorytety weryfikacji</h3><div class="micro-grid"><div class="micro-card"><h3>Bark i stożek rotatorów</h3><p>Zweryfikuj przebieg ścięgien, przyczepy oraz odróżnienie obłego większego od mięśni stożka.</p></div><div class="micro-card"><h3>Dół pachowy</h3><p>Sprawdź relacje pęczków splotu ramiennego względem tętnicy pachowej; drobnych gałęzi nie podpisuj bez jednoznacznego widoku.</p></div><div class="micro-card"><h3>Przedramię</h3><p>Trzy warstwy zginaczy; niezależne widoki dłoniowy i grzbietowy.</p></div><div class="micro-card"><h3>Ręka</h3><p>Osobno oceń rozcięgna, troczki, łuki dłoniowe, sieć żylną i ścięgna.</p></div></div><div class="note">Źródła: Gray t.1 (PDF ss. 393, 419, 437, 493–496, 512, 529–531), Sobotta t.1 (PDF ss. 202, 239, 250), Rohen–Yokochi (fotograficzne ujęcia kończyny górnej). Szczegóły i rejestry w plikach JSON dołączonych do ZIP.</div></section>`;}

// 4.51: priority workbench — risk labels are workflow cues, never anatomical certifications.
const TRIAGE454=JSON.parse(document.getElementById('atlas-triage454').textContent).records;
const triageLevels454=['all','wysoki','średni','standardowy'];let triageFilter454='all', triageText454='';
function triageHTML454(){
 const rows=Object.entries(TRIAGE454).filter(([k,v])=>(triageFilter454==='all'||v.risk===triageFilter454)&&norm(v.pl+' '+v.la+' '+k).includes(norm(triageText454)))
 .sort((a,b)=>({wysoki:0,'średni':1,standardowy:2}[a[1].risk]??3)-({wysoki:0,'średni':1,standardowy:2}[b[1].risk]??3));
 const flagged=Object.keys(state.reviewMarks).filter(k=>state.reviewMarks[k]==='wymaga-korekty').length;
 return `<section class="study triage454" style="max-width:1600px"><h2>Priorytety kontroli 4.64</h2><p class="muted">Wszystkie punkty są orientacyjne. Kategoria „wysoki” oznacza pierwszeństwo sprawdzenia, a nie wykrycie błędu. Weryfikacja graficzna i źródłowa wymaga oceny konkretnej planszy.</p><div class="auditstats"><span>${Object.keys(TRIAGE454).length} punktów</span><span>${flagged} zgłoszonych przez użytkownika</span><span>${Object.values(TRIAGE454).filter(v=>v.risk==='wysoki').length} priorytetów wysokich</span><span>0 pełnych walidacji atlasowych</span></div><div class="triageControls454"><label>Priorytet <select id="triageLevel454">${triageLevels454.map(v=>`<option value="${v}" ${triageFilter454===v?'selected':''}>${v==='all'?'Wszystkie':esc(v)}</option>`).join('')}</select></label><label>Wyszukaj <input id="triageQuery454" type="search" value="${esc(triageText454)}" placeholder="Mięsień, nerw, identyfikator..."></label><button class="btn" data-action="exportTriage454">Eksportuj priorytety CSV</button></div><div id="triageList454" class="triageList454">${triageRows454(rows)}</div><p class="note">Źródła i strony są odziedziczone z wcześniejszego audytu. Brak źródła przypisanego do danego punktu jest jawnie widoczny. Prywatne atlasy nie są dołączone do paczki publicznej.</p></section>`;
}
function triageRows454(rows){return rows.map(([key,r])=>`<article class="triageItem454"><img src="${esc(thumbnailURL(r.image))}" alt="" loading="lazy"><div><b>${esc(r.pl)}</b><small>${esc(r.la)} · ${esc(r.image)}</small><small>Źródło: ${esc(r.source)} · ${esc(r.reference)}</small><small>Ocena punktu: ${esc(reviewStatus(key))} · ${esc(r.reviewStatus)}</small></div><strong class="risk454 ${r.risk==='wysoki'?'riskHi454':''}">${esc(r.risk)}</strong><div class="triageActions454"><button data-triage-open="${esc(key)}">Otwórz</button><button data-triage-flag="${esc(key)}">⚑ Zgłoś</button></div></article>`).join('')||'<p class="note">Brak wyników wyszukiwania.</p>'}
function openTriage454(key){const rec=TRIAGE454[key];if(!rec)return;const region=regionForImage(rec.image);navigate(region);state.view='all';state.layer='all';state.imageId=rec.image;state.selected=rec.structure;render();}
function exportTriage454(){const rows=[['obraz','struktura','nazwa_pl','nazwa_lac','priorytet','pochodzenie','zrodlo_atlasowe','status_lokalny']];for(const [key,r] of Object.entries(TRIAGE454))rows.push([r.image,r.structure,r.pl,r.la,r.risk,r.source,r.reference,reviewStatus(key)]);const csv='\ufeff'+rows.map(cols=>cols.map(c=>'"'+String(c??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const uri=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=uri;a.download='gray454_priorytety.csv';a.click();setTimeout(()=>URL.revokeObjectURL(uri),1500);}

function mainHTML(){return state.tab==='audit'?reviewHTML():state.tab==='quality444'?quality444():state.tab==='triage454'?triageHTML454():state.tab==='work464'?reviewDashboard464():state.tab==='lab3d'?lab3DHTML():state.tab==='atlas'?atlasHTML():state.tab==='quiz'?quizHTML():state.tab==='cards'?cardsHTML():state.tab==='favorites'?favHTML():state.tab==='notes'?notesHTML():helpHTML();}
function render(){updateTitle();$('#sidebar').innerHTML=menuHTML();$('#appHead').innerHTML=headerHTML();$('#mainInner').innerHTML=mainHTML();if(state.tab==='lab3d'){const frame=$('#lab3dframe');if(frame){frame.addEventListener('load',()=>{if(state.bridgeMesh)frame.contentWindow?.postMessage({scope:'GRAY423',type:'select',meshId:state.bridgeMesh},'*')},{once:true});if(window.GRAY3DLAB){frame.removeAttribute('src');frame.srcdoc=window.GRAY3DLAB;}}}$$('details', $('#sidebar')).forEach(el=>{if(el.querySelector('.navitem.active'))el.open=true});}
function selectSearch(id,region){navigate(region);state.selected=id;state.searchOpen=false;state.globalQuery='';chooseStructure(id);}
window.addEventListener('message',e=>{
 const iframe=$('#lab3dframe');if(!iframe||e.source!==iframe.contentWindow||e.data?.scope!=='GRAY423')return;
 if(e.data.type==='ready'&&state.bridgeMesh)iframe.contentWindow.postMessage({scope:'GRAY423',type:'select',meshId:state.bridgeMesh},'*');
 if(e.data.type==='selected'){
  state.bridgeFrom3D=(typeof e.data.meshId==='string'&&MESH_BRIDGE[e.data.meshId])?e.data.meshId:null;
  const panel=$('.lab-bridge');if(panel){const b=panel.querySelector('button');if(b)b.disabled=!(state.bridgeFrom3D||state.bridgeReturn);const label=panel.querySelector('span');if(label)label.textContent=state.bridgeFrom3D?'Wybrano siatkę: '+state.bridgeFrom3D:'Niepowiązana siatka';}
 }
});

document.addEventListener('click',e=>{
 const triageOpen=e.target.closest('[data-triage-open]');if(triageOpen){openTriage454(triageOpen.dataset.triageOpen);return;}const triageFlag=e.target.closest('[data-triage-flag]');if(triageFlag){state.reviewMarks[triageFlag.dataset.triageFlag]='wymaga-korekty';save('gray421_markReviews',state.reviewMarks);render();return;}
 const button=e.target.closest('button');if(button){const reg=button.dataset.region;if(reg){navigate(reg);return}const t=button.dataset.tab;if(t){setTab(t);return}const view=button.dataset.view;if(view){setView(view);return}const layer=button.dataset.layer;if(layer){setLayer(layer);return}const im=button.dataset.image;if(im){imageById(im);return}const st=button.dataset.struct;if(st){chooseStructure(st);return}const dt=button.dataset.detailTab;if(dt){state.detailTab=dt;render();return}const ans=button.dataset.answer;if(ans!==undefined){answer(Number(ans));return}const res=button.dataset.searchId;if(res){selectSearch(res,button.dataset.searchRegion);return}const auditmark=button.dataset.auditmark;if(auditmark){const [im,id]=auditmark.split('|');const region=Object.keys(DATA.images).find(r=>(DATA.images[r]||[]).some(v=>v.id===im));navigate(region||'shoulder_atlas');imageById(im);state.selected=id;render();return}const auditimg=button.dataset.auditimg;if(auditimg){const region=Object.keys(DATA.images).find(r=>(DATA.images[r]||[]).some(v=>v.id===auditimg));navigate(region||'shoulder_atlas');imageById(auditimg);return}const favopen=button.dataset.favopen;if(favopen){const reg=DATA.atlas.find(s=>structures(s.id).some(x=>x.id===favopen));navigate(reg?.id||'shoulder_atlas');chooseStructure(favopen);return}
 switch(button.dataset.action){case 'exportAudit464':exportAudit464();break;case 'saveEvidence464':evidenceSave464();break;case 'undo464':undo464();break;case 'redo464':redo464();break;case 'safeOnly464':state.showOnlySafe=!state.showOnlySafe;render();break;case 'suggestImage464':suggestImage464();break;case 'prevMarked464':jumpMarked464(-1);break;case 'nextMarked464':jumpMarked464(1);break;case 'deepLayer464':jumpLayer464(1);break;case 'shallowLayer464':jumpLayer464(-1);break;case 'exportTriage454':exportTriage454();break;case 'share425':share425();break;case 'bridge3d':bridgeStart();break;case 'bridgeBack':bridgeBack();break;case 'spotMode':spotToggle();break;case 'spotNext':spotNext();break;case 'labels':toggleLabelsUI();break;case 'dots':state.showDots=!state.showDots;render();break;case 'plus':state.zoom=Math.min(3,state.zoom+.25);render();break;case 'minus':state.zoom=Math.max(1,state.zoom-.25);render();break;case 'resetZoom':state.zoom=1;render();break;case 'fullscreen':$('.viewer')?.requestFullscreen?.();break;case 'clearFilters':state.view='all';state.layer='all';state.imageId=allImages()[0]?.id||null;render();break;case 'toggleCompare':state.compare=state.compare==='off'?'side':'off';render();break;case 'compareSide':state.compare='side';render();break;case 'compareOverlay':state.compare='overlay';render();break;case 'editPoint':state.editPoint=!state.editPoint;render();break;case 'resetPoint':resetPoint();break;case 'copyPoint444':{const im=currentImage(),st=selected();const p=point(im,st?.id);if(p){const t=JSON.stringify({image_id:im.id,structure_id:st.id,xy:p,verification:'unverified'});navigator.clipboard?.writeText(t).then(()=>toast425('Współrzędne skopiowane.')).catch(()=>fallbackCopy425(t));if(!navigator.clipboard)fallbackCopy425(t)}else toast425('Brak punktu na tej rycinie.');break;}case 'export':exportCorrections();break;case 'exportCSV':exportCSV425();break;case 'reviewFlag':setReviewStatus('wymaga-korekty');break;case 'reviewSeen':setReviewStatus('przejrzano-lokalnie');break;case 'reviewClear':setReviewStatus('nieoceniony');break;case 'imageFlag':setImageReview('wymaga-korekty');break;case 'imageSeen':setImageReview('przejrzana-lokalnie');break;case 'imageClear':setImageReview('nieoceniona');break;case 'fav':if(state.selected)favorite(state.selected);break;case 'newQuiz':startQuiz();render();break;case 'quizMistakes':startMistakeQuiz425();render();break;case 'nextQuiz':state.quizIndex++;state.quizAnswer=null;render();break;case 'nextCard':state.flashIndex++;state.flashFlip=false;render();break;case 'prevCard':state.flashIndex=Math.max(0,state.flashIndex-1);state.flashFlip=false;render();break;case 'flip':state.flashFlip=!state.flashFlip;render();break;case 'saveNote':state.notes[state.region+'|'+(state.selected||'region')]=$('#noteText')?.value||'';save('gray418_notes',state.notes);alert('Notatka zapisana lokalnie.');break;case 'exportNotes':{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state.notes,null,2)],{type:'application/json'}));a.download='gray418_notatki.json';a.click();break}}return;
 }
 const hot=e.target.closest('circle.hotspot');if(hot?.dataset.struct){if(state.spotMode)spotGuess(hot.dataset.struct);else chooseStructure(hot.dataset.struct);return}const surf=e.target.closest('.image-surface');if(surf&&state.editPoint){editClick(e);return}
});
document.addEventListener('input',e=>{
 if(e.target.id==='triageQuery454'){triageText454=e.target.value;const list=document.getElementById('triageList454');if(list){const rows=Object.entries(TRIAGE454).filter(([k,v])=>(triageFilter454==='all'||v.risk===triageFilter454)&&norm(v.pl+' '+v.la+' '+k).includes(norm(triageText454))).sort((a,b)=>({wysoki:0,'średni':1,standardowy:2}[a[1].risk]??3)-({wysoki:0,'średni':1,standardowy:2}[b[1].risk]??3));list.innerHTML=triageRows454(rows);}return;}
 if(e.target.id==='globalSearch'){state.globalQuery=e.target.value;state.searchOpen=true;const head=$('#appHead');if(head){const old=$('.searchresults',head);if(old)old.remove();if(state.globalQuery.trim())head.insertAdjacentHTML('beforeend',searchHTML());}return}
 if(e.target.id==='structFilter'){state.filters=e.target.value;const list=$('.struct-list');if(!list)return;const im=currentImage();const matched=structures().filter(st=>[st.pl,st.la,st.en].some(n=>norm(n).includes(norm(state.filters))));list.innerHTML=matched.map(st=>`<button class="struct-item ${st.id===state.selected?'active':''}" data-struct="${esc(st.id)}"><span class="names"><b>${esc(st.pl)}</b><small>${esc(st.la||st.en||'')}</small></span><span class="dot ${point(im,st.id)?'yes':''}"></span></button>`).join('');return}
 if(e.target.id==='opacity'){state.opacity=Number(e.target.value);if($('#compareSecond'))$('#compareSecond').style.opacity=String(state.opacity/100);return}
});
document.addEventListener('change',e=>{if(e.target.id==='triageLevel454'){triageFilter454=e.target.value;render();return;}if(e.target.id==='compareId'){state.compareId=e.target.value;render()}if(e.target.id==='quizTotal'){state.quizTotal=Number(e.target.value);startQuiz();render()}});
