window.addEventListener('message',e=>{const frame=document.getElementById('dock3dframe424');if(!frame||e.source!==frame.contentWindow||e.data?.scope!=='GRAY424')return;if(e.data.type==='ready'){sendDepth424(depthAtlas424);if(state.selected)sendMesh424(state.selected);}if(e.data.type==='depth'){depthAtlas424=Math.max(0,Math.min(100,Number(e.data.value)||0));const lab=document.getElementById('depthDockLabel424');if(lab)lab.textContent=depthAtlas424+'%';const slider=document.getElementById('depthDockSlider424');if(slider)slider.value=String(depthAtlas424);}});
window.addEventListener('message',e=>{const frame=document.getElementById('dock3dframe424');if(!frame||e.source!==frame.contentWindow||e.data?.scope!=='GRAY423'||e.data.type!=='selected')return;const a=MESH_BRIDGE[e.data.meshId];if(a&&structures().some(s=>s.id===a)&&state.selected!==a){state.selected=a;render();}});
document.getElementById('depthDockSlider424')?.addEventListener('input',e=>sendDepth424(e.target.value));
