try{render()}catch(e){console.error(e);$('#mainInner').innerHTML=`<div class="errormsg">Nie udało się uruchomić atlasu. ${esc(e.message)}</div>`}
// 4.27: keyboard use consistent with open anatomy viewers; never intercept text inputs.
document.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey)return;const target=e.target;const typing=/^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName)||target.isContentEditable;
 if(e.key==='Escape'){if(state.searchOpen){state.searchOpen=false;state.globalQuery='';render();}else if(dockOpen424){setDock424(false);}return;}
 if(typing)return;
 if(e.key==='/'){e.preventDefault();document.getElementById('globalSearch')?.focus();return;}
 if(e.key==='?'&&!e.shiftKey){setTab('help');return;}
 if(e.key==='f'&&state.tab==='atlas'){state.favorites.has(state.selected)?state.favorites.delete(state.selected):state.selected&&state.favorites.add(state.selected);save('gray418_fav',[...state.favorites]);render();return;}
 if(state.tab!=='atlas')return;
 if(e.key==='ArrowRight'||e.key==='ArrowLeft'){const list=images();if(list.length<2)return;const ix=list.findIndex(im=>im.id===currentImage()?.id);state.imageId=list[(ix+(e.key==='ArrowRight'?1:-1)+list.length)%list.length].id;state.selected=null;render();}
 if(e.key==='l'){state.showLabels=!state.showLabels;render();}
 if(e.key==='d'){state.showDots=!state.showDots;render();}
 if(e.key==='3'){setDock424(!dockOpen424);}
});

